{
  "name": "Cobolt实验室激光器",
  "name_en": "Cobolt laboratory laser",
  "manufacturer": "Cobolt",
  "description": "一款用于实验室光学实验的激光光源，可控制激光开关与输出功率，并提供互锁、自启动和设备状态信息，适用于激发、照明、光路对准和一般光学测量。",
  "description_en": "A laboratory laser source for optical experiments. It supports laser on/off control, output power adjustment, and reporting of interlock, autostart, and device status, making it suitable for excitation, illumination, beam alignment, and general optical measurements.",
  "tag_hints": [
    "laser source",
    "optical experiments",
    "power control",
    "interlock safety",
    "autostart",
    "beam alignment"
  ],
  "actions": [
    {
      "action_name": "auto-autostartIsOn",
      "description": "获取是否启用自启动",
      "description_en": "Get whether autostart is enabled"
    },
    {
      "action_name": "auto-turnAutostartOn",
      "description": "启用自启动",
      "description_en": "Enable autostart"
    },
    {
      "action_name": "auto-turnAutostartOff",
      "description": "关闭自启动",
      "description_en": "Disable autostart"
    },
    {
      "action_name": "auto-doInitializeDevice",
      "description": "初始化激光器",
      "description_en": "Initialize the laser"
    },
    {
      "action_name": "auto-doShutdownDevice",
      "description": "关闭设备",
      "description_en": "Shut down the device"
    },
    {
      "action_name": "auto-doGetInterlockState",
      "description": "获取互锁状态",
      "description_en": "Get the interlock state"
    },
    {
      "action_name": "auto-doGetLaserSerialNumber",
      "description": "获取激光器序列号",
      "description_en": "Get the laser serial number"
    },
    {
      "action_name": "auto-doGetOnOffState",
      "description": "获取激光开关状态",
      "description_en": "Get the laser on/off state"
    },
    {
      "action_name": "auto-doTurnOn",
      "description": "打开激光输出",
      "description_en": "Turn on laser output"
    },
    {
      "action_name": "auto-doTurnOff",
      "description": "关闭激光输出",
      "description_en": "Turn off laser output"
    },
    {
      "action_name": "auto-doGetAutostart",
      "description": "获取自启动状态",
      "description_en": "Get the autostart state"
    },
    {
      "action_name": "auto-doTurnAutostartOn",
      "description": "启用自启动",
      "description_en": "Enable autostart"
    },
    {
      "action_name": "auto-doTurnAutostartOff",
      "description": "关闭自启动",
      "description_en": "Disable autostart"
    },
    {
      "action_name": "auto-doSetPower",
      "description": "设置激光输出功率",
      "description_en": "Set the laser output power"
    },
    {
      "action_name": "auto-doGetPower",
      "description": "获取激光输出功率",
      "description_en": "Get the laser output power"
    }
  ]
}

